create role anon;create role authenticated;create schema auth;create schema storage;
create table auth.users(id uuid primary key,email text,raw_user_meta_data jsonb default '{}');
create function auth.uid()returns uuid language sql stable as $$select nullif(current_setting('request.jwt.claim.sub',true),'')::uuid$$;
grant usage on schema auth,storage to authenticated;grant execute on function auth.uid()to authenticated;
create table storage.objects(id uuid primary key default gen_random_uuid(),bucket_id text,name text);alter table storage.objects enable row level security;grant all on storage.objects to authenticated;
create table public.empresas(id uuid primary key default gen_random_uuid(),cnpj text,nome_fantasia text,razao_social text,telefone text,endereco text);
create table public.perfis(id uuid primary key references auth.users(id),nome text,setor text,empresa_id uuid references empresas(id),is_admin boolean default false,is_socio boolean default false,is_gerente boolean default false,permissoes_socio text[] default '{}',permissoes_gerente text[] default '{}',pode_fechar_caixa boolean default false,cargo text default 'staff',avatar_url text,telefone_whatsapp text,salario_base numeric default 0,valor_diaria numeric default 0,tipo_contrato text default 'fixo',data_admissao date,dias_folga_semana text[] default '{}');
create table public.tarefas(id uuid primary key default gen_random_uuid(),empresa_id uuid,titulo text,instrucao text,prioridade text,categoria text,criado_por uuid references perfis(id),assumido_por uuid references perfis(id),destinado_a uuid,setor_destinado text,ajudantes uuid[] default '{}',subitens jsonb default '[]',status text default 'pendente',recorrente boolean default false,horario_reinicio text,ultimo_reinicio date,ordem integer default 0,autonoma boolean default false,hora_inicio timestamptz,hora_fim timestamptz,criado_em timestamptz default now(),aguardando_aprovacao boolean);
create table public.avisos(id uuid primary key default gen_random_uuid(),empresa_id uuid,titulo text,mensagem text,setor_destino text,criado_por uuid references perfis(id),destinado_a uuid,lidos_por uuid[] default '{}',tarefa_autonoma_id uuid references tarefas(id),ponto_freelance_id uuid,criado_em timestamptz default now(),fixo boolean default false);
create table public.livro_ponto(id uuid primary key default gen_random_uuid(),empresa_id uuid,perfil_id uuid references perfis(id),data_registro date,status_turno text,horario_entrada timestamptz,horario_saida timestamptz,criado_em timestamptz default now());
create table public.vales(id uuid primary key default gen_random_uuid(),empresa_id uuid,perfil_id uuid references perfis(id),criado_por uuid references perfis(id),valor numeric,data_vale date,observacao text,pago boolean default false,data_pagamento timestamptz);
create table public.itens_comprados(id uuid primary key default gen_random_uuid(),empresa_id uuid,perfil_id uuid references perfis(id),registrado_por uuid references perfis(id),descricao_item text,valor_unitario numeric,porcentagem_desconto numeric,valor_final numeric,data_compra date);
create table public.pedidos_compra(id uuid primary key default gen_random_uuid(),mensagem text,categoria text,status text default 'pendente',lido boolean default false,criado_por uuid references perfis(id),comprado_por uuid,criado_em timestamptz default now(),data_comprado date);
create table public.contas_pagar(id uuid primary key default gen_random_uuid(),fornecedor_descricao text,valor numeric,data_vencimento date,tipo_pagamento text,categoria text,codigo_barras_pix text,favorecido_pix text,status text default 'pendente',criado_por uuid references perfis(id),data_pagamento date);
create table public.fechamento_caixa(id uuid primary key default gen_random_uuid(),data_fechamento date,responsavel_id uuid references perfis(id),fundo_troco numeric,valor_dinheiro numeric,valor_pix numeric,valor_debito numeric,valor_credito numeric,sangrias numeric,total_entradas numeric,observacoes text,criado_em timestamptz default now());
create table public.cardapio_consumo(id uuid primary key default gen_random_uuid(),nome_item text,valor_padrao numeric,ativo boolean default true);
